body.policy:
path "sys/storage/raft/snapshot" { capabilities = ["read"] }
path "auth/token/lookup-self" { capabilities = ["read"] }
path "auth/token/revoke-self" { capabilities = ["update"] }
path "sys/capabilities-self" { capabilities = ["update"] }

path "sys/policies/acl/platform-deployment-maintainer" { capabilities = ["read", "update"] }
path "sys/policies/acl/endpoint-restricted-issuer" { capabilities = ["read", "update"] }
path "sys/policies/acl/trunk-restricted-issuer" { capabilities = ["read", "update"] }
path "auth/platform-backup/role/platform-raft-snapshot-reader/role-id" { capabilities = ["read"] }
path "auth/platform-backup/role/platform-raft-snapshot-reader/secret-id" { capabilities = ["update"] }
path "auth/platform-backup/role/platform-raft-snapshot-reader/secret-id-accessor/lookup" { capabilities = ["update"] }
path "auth/platform-backup/role/platform-raft-snapshot-reader/secret-id-accessor/destroy" { capabilities = ["update"] }
path "auth/token/lookup-self" { capabilities = ["read"] }
path "auth/token/revoke-self" { capabilities = ["update"] }
path "sys/capabilities-self" { capabilities = ["update"] }
